ALTER TABLE public.customer_payment_attempts ADD COLUMN provider_environment text NOT NULL DEFAULT 'live';
CREATE FUNCTION public.finance_validate_refund() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; committed bigint; item_max bigint; old_item bigint; recorded bigint; t public.customer_payment_attempts; used_credit bigint; used_external bigint; BEGIN IF TG_OP='INSERT' THEN SELECT * INTO o FROM public.orders WHERE id=NEW.order_id FOR UPDATE; IF o.total_cents IS NULL OR o.total_cents<=0 OR coalesce(o.refunded_cents,0)<0 OR coalesce(o.refunded_cents,0)>o.total_cents THEN RAISE EXCEPTION 'Invalid order accounting'; END IF; IF NEW.user_id IS DISTINCT FROM o.user_id THEN RAISE EXCEPTION 'Customer mismatch'; END IF; SELECT coalesce(sum(amount_cents),0) INTO committed FROM public.customer_refunds WHERE order_id=o.id AND status NOT IN ('revoked','declined','credited','refunded'); IF NEW.amount_cents>o.total_cents-coalesce(o.refunded_cents,0)-committed THEN RAISE EXCEPTION 'Refund exceeds available entitlement'; END IF; END IF;
IF TG_OP='UPDATE' AND NEW.status IN ('credited','refunded') AND OLD.status NOT IN ('credited','refunded') THEN IF NEW.item_id IS NOT NULL THEN UPDATE public.order_items SET refund_cents=coalesce(refund_cents,0)+NEW.amount_cents WHERE id=NEW.item_id; END IF; END IF;
IF TG_OP='UPDATE' AND NEW.status='processing' AND OLD.status='approved' THEN SELECT * INTO t FROM public.customer_payment_attempts WHERE order_id=NEW.order_id AND status='approved'; IF FOUND THEN SELECT coalesce(sum(credit_cents),0),coalesce(sum(provider_cents),0) INTO used_credit,used_external FROM public.customer_refunds WHERE order_id=NEW.order_id AND id<>NEW.id AND status IN ('processing','review','failed','refunded'); IF NEW.credit_cents>greatest(0,t.credit_cents-used_credit) OR NEW.provider_cents>greatest(0,t.provider_cents-used_external) THEN RAISE EXCEPTION 'Original tender ceiling exceeded'; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER finance_refund_validation BEFORE INSERT OR UPDATE ON public.customer_refunds FOR EACH ROW EXECUTE FUNCTION public.finance_validate_refund();
CREATE FUNCTION public.finance_block_legacy_refund() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.refunded_cents IS DISTINCT FROM OLD.refunded_cents AND pg_trigger_depth()=1 AND EXISTS(SELECT 1 FROM public.customer_refunds WHERE order_id=NEW.id AND status NOT IN ('revoked','declined')) THEN IF current_setting('finance.refund_operation',true) IS DISTINCT FROM 'active' THEN RAISE EXCEPTION 'Refund must use central finance operation'; END IF; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.finance_rpc_context() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN PERFORM set_config('finance.refund_operation','active',true); RETURN NEW; END $$;
CREATE TRIGGER finance_refund_context BEFORE INSERT OR UPDATE ON public.customer_refunds FOR EACH ROW EXECUTE FUNCTION public.finance_rpc_context();
COMMENT ON COLUMN public.orders.store_credit_cents IS 'Customer monetary tender; separate from voucher discount wallet_deduction_cents';